import { describe, expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import {
  createBalancedTsAccountShardAssignment,
  normalizeTsWorkerAccountId,
  TS_ACCOUNT_LOGICAL_SHARDS,
  tsAccountLogicalShard,
  tsAccountWorkerForShard,
  validateTsAccountShardAssignment,
} from '../../../rscore/ts-worker/sharding';

/**
 * Golden shard vectors generated by executing the authoritative Rust crate
 * (rscore/crates/protocol `PersistentRadixMap::into_three_nibble_shards`) with
 * one Account key per logical shard plus adversarial all-boundary keys
 * (0x000..., 0xfff..., 0x0fff..., 0x1000..., 0xfffe...01). Each entry is
 * [accountId, rustResolvedShard]. The TS mapping must reproduce every one.
 */
const VECTORS_PATH = join(import.meta.dir, 'ts-worker-shard-vectors.json');
type ShardVectors = Readonly<{ rustShardCount: number; vectors: readonly (readonly [string, number])[] }>;
const vectors = JSON.parse(readFileSync(VECTORS_PATH, 'utf8')) as ShardVectors;

describe('TS Account worker shard mapping (Rust parity)', () => {
  test('golden vectors agree with the live Rust resident shard split', () => {
    expect(vectors.rustShardCount).toBe(4096);
    expect(TS_ACCOUNT_LOGICAL_SHARDS).toBe(4096);
    expect(vectors.vectors).toHaveLength(4096 + 5);
    const seenShards = new Set<number>();
    for (const [accountId, rustShard] of vectors.vectors) {
      expect(tsAccountLogicalShard(accountId)).toBe(rustShard);
      seenShards.add(rustShard);
    }
    expect(seenShards.size).toBe(4096);
  });

  test('every prefix boundary key maps to the fold of its first three nibbles', () => {
    for (let shard = 0; shard < 4096; shard += 1) {
      const first = ((shard >> 8) & 0x0f).toString(16);
      const second = ((shard >> 4) & 0x0f).toString(16);
      const third = (shard & 0x0f).toString(16);
      const suffix = '0'.repeat(61);
      expect(tsAccountLogicalShard(`0x${first}${second}${third}${suffix}`)).toBe(shard);
    }
  });

  test('rejects malformed ids instead of guessing a shard', () => {
    expect(() => tsAccountLogicalShard('0x123')).toThrow('TS_ACCOUNT_WORKER_ACCOUNT_ID_INVALID');
    expect(() => tsAccountLogicalShard(`0x${'g'.repeat(64)}`)).toThrow('TS_ACCOUNT_WORKER_ACCOUNT_ID_INVALID');
    expect(normalizeTsWorkerAccountId(`0x${'0A'.repeat(32)}`)).toBe(`0x${'0a'.repeat(32)}`);
  });
});

describe('deterministic shard ownership', () => {
  for (const workerCount of [1, 2, 4, 8]) {
    test(`balanced assignment for ${workerCount} worker(s) owns every shard exactly once`, () => {
      const assignment = validateTsAccountShardAssignment(
        createBalancedTsAccountShardAssignment(workerCount),
        workerCount,
      );
      expect(assignment).toHaveLength(4096);
      // Deterministic for the process lifetime: same input, same owner.
      expect(createBalancedTsAccountShardAssignment(workerCount)).toEqual(assignment);
      const owned = Array.from({ length: workerCount }, () => 0);
      for (let shard = 0; shard < 4096; shard += 1) {
        const worker = tsAccountWorkerForShard(shard, assignment);
        expect(worker).toBeGreaterThanOrEqual(0);
        expect(worker).toBeLessThan(workerCount);
        owned[worker] += 1;
      }
      expect(owned.every(count => count === 4096 / workerCount)).toBeTrue();
    });
  }

  test('rejects assignments with empty workers or out-of-range slots', () => {
    expect(() => validateTsAccountShardAssignment([0], 1)).toThrow('TS_ACCOUNT_WORKER_ASSIGNMENT_LENGTH');
    expect(() => createBalancedTsAccountShardAssignment(0)).toThrow('TS_ACCOUNT_WORKER_COUNT_INVALID');
    expect(() => tsAccountWorkerForShard(4096, createBalancedTsAccountShardAssignment(1)))
      .toThrow('TS_ACCOUNT_WORKER_SHARD_INVALID');
  });
});
